-- 003_seed.sql — Civic Fix demo data (generated, deterministic)
-- Run THIRD, after 001_schema.sql and 002_functions.sql. Safe to re-run: it first removes previous seed rows.
--
-- Contents: 6 categories, 5 departments, 6 demo profiles (5 citizens + 1 admin), 80 reports around Nagpur
-- (approximate locality coordinates, a few tight clusters for the heatmap), status history, comments, notifications,
-- and report_images rows pointing at placeholder files in the `report-images` bucket under `seed/`
-- (upload server/sql/seed-images/* there, see docs/database.md §9).
--
-- Seed exception: reports.upvote_count is set directly here (the upvotes trigger only fires for real upvote rows,
-- and there are only 6 demo profiles). Real user upvotes/un-upvotes then +1/-1 on top through the trigger.

begin;

-- Remove previous seed data only (real users' ids never start with user_seed_).
delete from reports  where starts_with(reporter_id, 'user_seed_');
delete from profiles where starts_with(id, 'user_seed_');


-- Lookup data
insert into categories (slug, name, icon) values
  ('pothole', 'Pothole', 'construction'),
  ('garbage', 'Garbage', 'trash-2'),
  ('streetlight', 'Streetlight', 'lamp'),
  ('water_leak', 'Water Leak', 'droplets'),
  ('drainage', 'Drainage', 'waves'),
  ('other', 'Other', 'ellipsis')
on conflict (slug) do nothing;

insert into departments (name) values
  ('Roads'),
  ('Sanitation'),
  ('Electricity'),
  ('Water Supply'),
  ('Drainage')
on conflict (name) do nothing;

-- Demo profiles (fake Clerk-style ids)
insert into profiles (id, display_name) values
  ('user_seed_01', 'Rahul Sharma'),
  ('user_seed_02', 'Priya Deshmukh'),
  ('user_seed_03', 'Amit Kulkarni'),
  ('user_seed_04', 'Sneha Patil'),
  ('user_seed_05', 'Vikram Joshi'),
  ('user_seed_admin', 'City Admin');

-- Reports
insert into reports (id, reporter_id, category_id, department_id, title, description, status, severity, location, area_name, upvote_count, reject_reason, created_at, updated_at, resolved_at)
select v.id::uuid, v.reporter_id, c.id, d.id, v.title, v.description, v.status::report_status, v.severity::smallint,
       st_setsrid(st_makepoint(v.lng::float8, v.lat::float8), 4326)::geography, v.area_name, v.upvotes::int, v.reject_reason,
       now() - interval '1 hour' * v.created_ago::float8,
       now() - interval '1 hour' * v.updated_ago::float8,
       case when v.resolved_ago is null then null else now() - interval '1 hour' * v.resolved_ago::float8 end
